insert into public.questoes (id, materia, nivel, enunciado, opcoes, explicacao)
select id, materia, nivel, enunciado, opcoes, explicacao
from jsonb_to_recordset($q$[{"id":3439,"materia":"adua","nivel":0,"enunciado":"Contrabando, no Código Penal, é importar ou exportar mercadoria:","opcoes":["Proibida","Com o imposto pago a mais","Com nota fiscal correta","Usada pelo próprio viajante"],"explicacao":"Iludir o pagamento do imposto devido é descaminho."},{"id":3440,"materia":"adua","nivel":0,"enunciado":"A declaração usada hoje no Brasil para o despacho de exportação é a:","opcoes":["DU-E (Declaração Única de Exportação)","DIRPF","DCTF (Declaração de Débitos e Créditos Tributários Federais)","GFIP"],"explicacao":"Registrada no Portal Único Siscomex."},{"id":3441,"materia":"adua","nivel":0,"enunciado":"Mercadoria nacionalizada é a mercadoria estrangeira:","opcoes":["Importada a título definitivo","Fabricada no Brasil","Que só passou pelo país em trânsito para outro destino","Apreendida pela polícia"],"explicacao":"Após o despacho para consumo."},{"id":3442,"materia":"adua","nivel":1,"enunciado":"Descaminho, no Código Penal, consiste em:","opcoes":["Iludir, no todo ou em parte, o imposto devido pela entrada ou saída de mercadoria","Importar mercadoria proibida","Transportar carga sem nota fiscal no mercado interno, entre estados vizinhos, sem recolher o ICMS","Falsificar moeda estrangeira"],"explicacao":"Art. 334 do CP. Contrabando é o art. 334-A."},{"id":3443,"materia":"adua","nivel":1,"enunciado":"A Tarifa Externa Comum (TEC), que fixa as alíquotas do Imposto de Importação, é adotada no âmbito do:","opcoes":["Mercosul","Nafta","G20","Brics ampliado"],"explicacao":"Baseia-se na Nomenclatura Comum do Mercosul (NCM)."},{"id":3444,"materia":"adua","nivel":1,"enunciado":"A Nomenclatura Comum do Mercosul (NCM) classifica as mercadorias com códigos de:","opcoes":["8 dígitos","6 dígitos","4 dígitos","12 dígitos"],"explicacao":"Os 6 primeiros vêm do Sistema Harmonizado (SH)."},{"id":3445,"materia":"adua","nivel":1,"enunciado":"Nos termos da CF, as alíquotas do Imposto de Importação podem ser alteradas:","opcoes":["Pelo Poder Executivo, nos limites e condições da lei","Somente por lei complementar","Apenas por emenda constitucional aprovada em dois turnos","Só no exercício seguinte"],"explicacao":"Art. 153, § 1º. É exceção às anterioridades anual e nonagesimal."},{"id":3446,"materia":"adua","nivel":2,"enunciado":"Pelo Regulamento Aduaneiro, o valor aduaneiro inclui, além do preço da mercadoria:","opcoes":["Frete e seguro até o porto ou aeroporto de descarga no Brasil","Apenas o preço pago ao exportador, sem frete nem seguro internacional","O lucro do importador na revenda","Os tributos internos brasileiros"],"explicacao":"Art. 77 do Regulamento Aduaneiro (base equivalente ao CIF)."},{"id":3447,"materia":"adua","nivel":2,"enunciado":"O ex-tarifário é a redução temporária do Imposto de Importação para:","opcoes":["Bens de capital e de informática sem produção nacional equivalente","Qualquer produto importado por pessoa física para uso próprio, sem limite","Bebidas e cigarros","Mercadorias usadas"],"explicacao":"Concedida por resolução do comitê executivo da Camex."},{"id":3448,"materia":"adua","nivel":2,"enunciado":"Na importação por conta e ordem de terceiro, o adquirente da mercadoria responde pelo Imposto de Importação:","opcoes":["Solidariamente com o importador","Sozinho, afastando o importador","Apenas se o importador falir","Nunca, pois não é parte"],"explicacao":"Previsto no Decreto-Lei 37/1966 e no Regulamento Aduaneiro."},{"id":3449,"materia":"adua","nivel":2,"enunciado":"O depósito alfandegado certificado (DAC) admite mercadoria nacional que:","opcoes":["Já foi vendida ao exterior e é considerada exportada para todos os efeitos","Ainda será fabricada","Será vendida no mercado interno, depois de passar pelo controle aduaneiro especial","Foi abandonada pelo importador"],"explicacao":"Arts. 493 e seguintes do Regulamento Aduaneiro."},{"id":3450,"materia":"adua","nivel":2,"enunciado":"O depósito afiançado permite armazenar, com suspensão de tributos:","opcoes":["Materiais de manutenção e reparo de veículos de empresa estrangeira de transporte internacional","Bebidas para venda em bares","Mercadorias apreendidas","Bens de mudança de diplomatas estrangeiros e de suas famílias, sem prazo nem garantia exigida"],"explicacao":"Exige garantia (fiança)."},{"id":3451,"materia":"adua","nivel":2,"enunciado":"No despacho de importação, o canal amarelo de parametrização determina:","opcoes":["Exame documental e, não havendo irregularidade, desembaraço sem verificação física","Desembaraço automático","Verificação física obrigatória","Procedimento especial por suspeita de fraude no valor declarado, com retenção da carga"],"explicacao":"Art. 21 da IN SRF 680/2006."},{"id":3452,"materia":"adua","nivel":3,"enunciado":"Pela Lei 10.865/2004, as alíquotas gerais do PIS-Importação e da Cofins-Importação sobre bens são de:","opcoes":["2,1% e 9,65%","1,65% e 7,6%","0,65% e 3%","3% e 12%"],"explicacao":"Art. 8º, com redação da Lei 13.137/2015."},{"id":3453,"materia":"adua","nivel":3,"enunciado":"O IPI vinculado à importação tem como fato gerador:","opcoes":["O desembaraço aduaneiro do produto de procedência estrangeira","A entrada do navio em águas brasileiras, com o registro do manifesto","A venda do produto ao consumidor","O pagamento do câmbio"],"explicacao":"Art. 46, I do CTN."},{"id":3454,"materia":"adua","nivel":3,"enunciado":"A falta de licença de importação, quando exigida, sujeita o importador à multa de:","opcoes":["30% do valor aduaneiro","100% do valor aduaneiro","5% do valor aduaneiro","10 salários mínimos"],"explicacao":"Art. 706, I, 'a' do Regulamento Aduaneiro."},{"id":3455,"materia":"adua","nivel":3,"enunciado":"A cota de isenção para bens na bagagem de viajante que chega ao Brasil por via aérea é de:","opcoes":["US$ 1.000","US$ 500","US$ 300","US$ 3.000"],"explicacao":"Por via terrestre, fluvial ou lacustre, US$ 500."},{"id":3456,"materia":"adua","nivel":3,"enunciado":"As Zonas de Processamento de Exportação (ZPE) são criadas por:","opcoes":["Decreto do Presidente da República, a partir de proposta de estados ou municípios","Lei municipal","Resolução do Banco Central, depois de consulta pública ao setor exportador interessado","Ato do próprio exportador"],"explicacao":"Lei 11.508/2007."},{"id":3457,"materia":"adua","nivel":4,"enunciado":"O Fundaf, previsto no Decreto-Lei 1.437/1975, destina-se a:","opcoes":["Financiar o reaparelhamento e a fiscalização da Receita Federal","Indenizar importadores prejudicados","Custear a Marinha Mercante","Pagar restituições do imposto de renda a contribuintes com prioridade"],"explicacao":"Fundo Especial de Desenvolvimento e Aperfeiçoamento das Atividades de Fiscalização."},{"id":3458,"materia":"adua","nivel":4,"enunciado":"O Imposto de Exportação tem alíquota de 30%, que o Poder Executivo pode elevar até o limite de:","opcoes":["150%","60%","100%","300%"],"explicacao":"Decreto-Lei 1.578/1977, art. 3º."},{"id":3459,"materia":"adua","nivel":4,"enunciado":"Na exportação, considera-se ocorrido o fato gerador do Imposto de Exportação na data:","opcoes":["Do registro da declaração de exportação no Siscomex","Do embarque da mercadoria","Do recebimento do pagamento","Da emissão da nota fiscal de saída pelo estabelecimento"],"explicacao":"Art. 213, parágrafo único do Regulamento Aduaneiro."},{"id":3460,"materia":"adua","nivel":4,"enunciado":"O Recom é o regime especial de importação de insumos destinados à industrialização por encomenda de:","opcoes":["Veículos das posições 8701 a 8705 da NCM","Navios e aeronaves","Medicamentos","Equipamentos de informática e telecomunicações"],"explicacao":"Como tratores, ônibus, automóveis e caminhões."},{"id":3461,"materia":"eco","nivel":0,"enunciado":"Inflação é o aumento:","opcoes":["Generalizado e contínuo dos preços","De um único preço","Do número de empregos formais","Das exportações"],"explicacao":"Medida por índices de preços."},{"id":3462,"materia":"eco","nivel":0,"enunciado":"Exportar é:","opcoes":["Vender bens ou serviços para outros países","Comprar bens e serviços de outros países","Emitir moeda","Cobrar impostos"],"explicacao":"Importar é comprar do exterior."},{"id":3463,"materia":"eco","nivel":1,"enunciado":"Na fronteira de possibilidades de produção, um ponto dentro da curva indica:","opcoes":["Uso ineficiente dos recursos","Produção impossível","Máxima eficiência","Crescimento econômico acelerado"],"explicacao":"Pontos sobre a curva são eficientes; fora dela, inatingíveis."},{"id":3464,"materia":"eco","nivel":1,"enunciado":"São variáveis-estoque, e não variáveis-fluxo:","opcoes":["A dívida pública e a riqueza","O PIB e a renda nacional","O consumo e o investimento","As exportações e importações do ano"],"explicacao":"Estoques são medidos em um instante; fluxos, ao longo de um período."},{"id":3465,"materia":"eco","nivel":1,"enunciado":"Quando a elasticidade-preço cruzada entre dois bens é positiva, eles são:","opcoes":["Substitutos","Complementares","Inferiores","Independentes"],"explicacao":"Se o preço de um sobe, a demanda do outro sobe."},{"id":3466,"materia":"eco","nivel":1,"enunciado":"Uma política monetária contracionista se caracteriza por:","opcoes":["Elevar a taxa de juros","Reduzir a taxa de juros","Aumentar os gastos do governo","Reduzir os impostos"],"explicacao":"Busca conter a inflação."},{"id":3467,"materia":"eco","nivel":1,"enunciado":"A desvalorização do real em relação ao dólar tende a:","opcoes":["Favorecer as exportações brasileiras","Baratear as importações","Reduzir a receita dos exportadores em reais","Eliminar o déficit público"],"explicacao":"Produtos brasileiros ficam mais baratos lá fora."},{"id":3468,"materia":"eco","nivel":2,"enunciado":"O excedente do consumidor é:","opcoes":["A diferença entre o que ele estaria disposto a pagar e o preço pago","O lucro da empresa vendedora","A renda que ele poupa no mês depois de pagar todas as despesas fixas","O imposto embutido no preço"],"explicacao":"Medida do bem-estar do consumidor."},{"id":3469,"materia":"eco","nivel":2,"enunciado":"Um monopólio natural surge quando:","opcoes":["Os custos médios caem com a escala, tornando mais eficiente uma só empresa","O governo proíbe a concorrência por lei para proteger uma empresa estatal estratégica","A empresa descobre um recurso natural","Há muitas empresas pequenas"],"explicacao":"Ex.: redes de distribuição de água e energia."},{"id":3470,"materia":"eco","nivel":2,"enunciado":"Pela teoria da vantagem comparativa, um país deve se especializar no bem que produz com:","opcoes":["Menor custo de oportunidade","Maior custo absoluto","Mais mão de obra","Maior preço internacional no mercado"],"explicacao":"Conceito de David Ricardo."},{"id":3471,"materia":"eco","nivel":2,"enunciado":"No balanço de pagamentos, a renda primária (juros e lucros) é registrada em:","opcoes":["Transações correntes","Conta financeira","Conta capital","Reservas internacionais"],"explicacao":"Junto com balança comercial, serviços e renda secundária."},{"id":3472,"materia":"eco","nivel":2,"enunciado":"A curva de Phillips original sugere uma relação:","opcoes":["Inversa entre inflação e desemprego no curto prazo","Direta entre inflação e emprego no longo prazo, em qualquer economia","Inexistente entre preços e emprego","Direta entre juros e câmbio"],"explicacao":"Mais tarde foi revista com as expectativas."},{"id":3473,"materia":"eco","nivel":2,"enunciado":"O resultado primário do governo é a diferença entre receitas e despesas:","opcoes":["Excluídos os juros da dívida","Incluídos todos os juros da dívida","Apenas com pessoal","Apenas de capital"],"explicacao":"O resultado nominal inclui os juros."},{"id":3474,"materia":"eco","nivel":3,"enunciado":"Um tributo é regressivo quando:","opcoes":["Pesa proporcionalmente mais sobre quem tem menor renda","Tem alíquota maior para quem ganha mais, conforme faixas de renda","Incide apenas sobre o patrimônio","É cobrado só uma vez"],"explicacao":"Tributos sobre consumo costumam ser regressivos."},{"id":3475,"materia":"eco","nivel":3,"enunciado":"O 'mercado de limões' de Akerlof ilustra o problema de:","opcoes":["Assimetria de informação e seleção adversa","Excesso de oferta agrícola","Externalidade positiva","Monopsônio no mercado de trabalho rural"],"explicacao":"Carros usados ruins expulsam os bons do mercado."},{"id":3476,"materia":"eco","nivel":3,"enunciado":"Estagflação é a situação em que ocorrem ao mesmo tempo:","opcoes":["Inflação alta e economia estagnada","Deflação e crescimento rápido","Pleno emprego e preços estáveis no longo prazo","Superávit externo e juros zero"],"explicacao":"Típica de choques de oferta, como o do petróleo nos anos 1970."},{"id":3477,"materia":"eco","nivel":3,"enunciado":"O comportamento de manada, na economia comportamental, ocorre quando as pessoas:","opcoes":["Imitam as decisões da maioria, mesmo sem informação própria","Decidem sempre isoladamente","Calculam todos os riscos com precisão antes de cada decisão","Evitam qualquer investimento"],"explicacao":"Ajuda a explicar bolhas especulativas."},{"id":3478,"materia":"eco","nivel":4,"enunciado":"No longo prazo, com a incorporação das expectativas, a curva de Phillips tende a ser:","opcoes":["Vertical, na taxa natural de desemprego","Horizontal","Negativamente inclinada sempre, em qualquer prazo","Positivamente inclinada"],"explicacao":"Contribuição de Friedman e Phelps."},{"id":3479,"materia":"eco","nivel":4,"enunciado":"O G20 reúne as maiores economias do mundo e, desde 2023, inclui como membros a União Europeia e a:","opcoes":["União Africana","Liga Árabe e a Opep","Opep","Asean"],"explicacao":"O Brasil presidiu o G20 em 2024."},{"id":3480,"materia":"eco","nivel":4,"enunciado":"O teto de gastos da EC 95/2016 limitava o crescimento das despesas primárias:","opcoes":["À inflação do ano anterior","Ao crescimento do PIB real","À arrecadação do ano","A zero, por 10 anos"],"explicacao":"Foi substituído pelo regime fiscal sustentável (LC 200/2023)."},{"id":3481,"materia":"aud","nivel":0,"enunciado":"O auditor deve manter, durante toda a auditoria, uma postura de:","opcoes":["Ceticismo profissional","Confiança total na administração","Parceria comercial com o cliente","Desinteresse pelos controles"],"explicacao":"Mente questionadora e avaliação crítica das evidências."},{"id":3482,"materia":"aud","nivel":0,"enunciado":"A auditoria interna é feita por:","opcoes":["Empregados ou setor da própria entidade","Auditor independente contratado pelos acionistas","Fiscais da Receita","Juízes"],"explicacao":"A auditoria externa é feita por auditor independente."},{"id":3483,"materia":"aud","nivel":1,"enunciado":"Pela NBC TA 240, a responsabilidade principal pela prevenção e detecção de fraudes é:","opcoes":["Da administração e dos responsáveis pela governança","Exclusiva do auditor independente","Do Conselho Federal de Contabilidade e dos conselhos regionais","Da Receita Federal"],"explicacao":"O auditor busca segurança razoável, não garantia."},{"id":3484,"materia":"aud","nivel":1,"enunciado":"A diferença essencial entre fraude e erro está:","opcoes":["Na intenção de quem pratica o ato","No valor envolvido","No setor da empresa","No momento da descoberta pelo auditor"],"explicacao":"Fraude é intencional; erro, não."},{"id":3485,"materia":"aud","nivel":1,"enunciado":"A opinião com ressalva é emitida quando a distorção é:","opcoes":["Relevante, mas não generalizada","Relevante e generalizada nas contas","Irrelevante","Inexistente"],"explicacao":"NBC TA 705."},{"id":3486,"materia":"aud","nivel":1,"enunciado":"São procedimentos de auditoria previstos na NBC TA 500, entre outros:","opcoes":["Inspeção, observação, indagação, confirmação e recálculo","Penhora, arresto e sequestro","Lançamento, cobrança e inscrição em dívida ativa da União","Denúncia, citação e sentença"],"explicacao":"Também reexecução e procedimentos analíticos."},{"id":3487,"materia":"aud","nivel":2,"enunciado":"Procedimentos analíticos consistem em avaliar informações contábeis por meio de:","opcoes":["Relações plausíveis entre dados financeiros e não financeiros","Contagem física de todo o estoque","Entrevistas com clientes da empresa sobre a qualidade dos produtos","Leitura das atas do conselho"],"explicacao":"Ex.: comparar margens de um ano com as do anterior."},{"id":3488,"materia":"aud","nivel":2,"enunciado":"O acompanhamento da contagem física dos estoques pelo auditor é tratado na:","opcoes":["NBC TA 501","NBC TA 700","NBC TA 320","NBC TA 230"],"explicacao":"Evidência de existência e condição dos estoques."},{"id":3489,"materia":"aud","nivel":2,"enunciado":"A materialidade (relevância) na auditoria serve para:","opcoes":["Planejar o trabalho e avaliar o efeito das distorções","Definir os honorários do auditor","Escolher o regime tributário mais vantajoso para a empresa","Calcular a depreciação"],"explicacao":"NBC TA 320."},{"id":3490,"materia":"aud","nivel":2,"enunciado":"Ao buscar passivos não registrados (subavaliação), o auditor costuma examinar:","opcoes":["Pagamentos feitos logo após a data do balanço","Apenas os saldos já contabilizados no razão geral","Somente as vendas do último dia","Os estoques de produtos acabados"],"explicacao":"Pagamentos posteriores podem revelar dívidas omitidas."},{"id":3491,"materia":"aud","nivel":2,"enunciado":"Suprimentos de caixa feitos por sócios, sem comprovação da origem e da entrega dos recursos, permitem ao Fisco presumir:","opcoes":["Omissão de receitas","Aumento regular de capital","Doação isenta","Ganho de capital"],"explicacao":"Os recursos podem vir de vendas não registradas."},{"id":3492,"materia":"aud","nivel":2,"enunciado":"A superavaliação de estoques finais provoca, no resultado do exercício:","opcoes":["Redução do CMV e aumento indevido do lucro","Aumento do CMV e redução do lucro líquido","Nenhum efeito","Aumento das receitas de vendas"],"explicacao":"CMV = EI + compras − EF."},{"id":3493,"materia":"aud","nivel":3,"enunciado":"Pela NBC TA 701, os principais assuntos de auditoria (PAA) devem ser comunicados no relatório de auditoria de:","opcoes":["Entidades com ações listadas em bolsa","Toda microempresa","Órgãos públicos municipais de pequeno porte","Pessoas físicas"],"explicacao":"Assuntos de maior importância segundo o julgamento do auditor."},{"id":3494,"materia":"aud","nivel":3,"enunciado":"Quando há incerteza relevante sobre a continuidade operacional adequadamente divulgada, o auditor inclui no relatório:","opcoes":["Seção específica sobre a incerteza, sem modificar a opinião","Opinião adversa obrigatória","Abstenção de opinião obrigatória","Nada, pois a continuidade não é assunto da auditoria"],"explicacao":"NBC TA 570."},{"id":3495,"materia":"aud","nivel":3,"enunciado":"As representações formais (carta de representação) são obtidas:","opcoes":["Da administração da entidade auditada","Dos clientes da entidade auditada","Dos bancos","Dos fornecedores"],"explicacao":"NBC TA 580; não substituem outras evidências."},{"id":3496,"materia":"aud","nivel":3,"enunciado":"Na amostragem estatística, a estratificação consiste em:","opcoes":["Dividir a população em subgrupos homogêneos","Escolher os itens por conveniência do auditor","Examinar 100% dos itens","Descartar os maiores valores"],"explicacao":"Aumenta a eficiência da amostra."},{"id":3497,"materia":"aud","nivel":3,"enunciado":"Ativos ocultos são bens da empresa que:","opcoes":["Existem, mas não estão registrados na contabilidade","Estão contabilizados em duplicidade no ativo imobilizado","Foram vendidos e baixados","Pertencem aos sócios"],"explicacao":"Podem indicar compra com recursos não contabilizados."},{"id":3498,"materia":"aud","nivel":4,"enunciado":"A baixa fictícia de títulos a receber, ainda não recebidos, costuma servir para:","opcoes":["Esconder recebimentos desviados ou receitas omitidas","Aumentar o ativo circulante","Reduzir o capital social","Registrar reservas de lucros e dividendos a distribuir"],"explicacao":"Item do edital de auditoria fiscal."},{"id":3499,"materia":"aud","nivel":4,"enunciado":"O auditor que, depois da data do relatório, toma conhecimento de fato que poderia alterá-lo deve seguir a norma sobre:","opcoes":["Eventos subsequentes (NBC TA 560)","Amostragem (NBC TA 530)","Materialidade (NBC TA 320)","Partes relacionadas e transações entre elas (NBC TA 550)"],"explicacao":"Inclui fatos conhecidos após a emissão do relatório."},{"id":3500,"materia":"dados","nivel":0,"enunciado":"Dados guardados em tabelas, com linhas e colunas bem definidas, são dados:","opcoes":["Estruturados","Não estruturados","Criptografados","Corrompidos"],"explicacao":"Textos livres, imagens e áudios são não estruturados."},{"id":3501,"materia":"dados","nivel":0,"enunciado":"Na ciência de dados, a nuvem (cloud computing) significa:","opcoes":["Usar recursos de computação pela internet, sob demanda","Guardar arquivos apenas em pen drive ou disco externo do usuário","Trabalhar sem nenhum computador","Imprimir relatórios em papel"],"explicacao":"Ex.: AWS, Azure e Google Cloud."},{"id":3502,"materia":"dados","nivel":1,"enunciado":"Arquivos JSON e XML são exemplos de dados:","opcoes":["Semiestruturados","Totalmente estruturados","Não estruturados","Binários executáveis"],"explicacao":"Têm marcações e hierarquia, mas sem esquema rígido de tabela."},{"id":3503,"materia":"dados","nivel":1,"enunciado":"A análise que responde à pergunta 'o que vai acontecer?' é a:","opcoes":["Preditiva","Descritiva","Diagnóstica","Retroativa"],"explicacao":"Descritiva: o que aconteceu; diagnóstica: por quê; prescritiva: o que fazer."},{"id":3504,"materia":"dados","nivel":1,"enunciado":"A análise prescritiva busca responder:","opcoes":["O que deve ser feito","O que aconteceu","Por que aconteceu o fato","Quanto custou"],"explicacao":"É o nível mais avançado de analytics."},{"id":3505,"materia":"dados","nivel":1,"enunciado":"No modelo SaaS de nuvem, o usuário:","opcoes":["Usa um software pronto pela internet","Recebe apenas máquinas virtuais","Recebe apenas uma plataforma para programar","Compra o servidor físico"],"explicacao":"IaaS: infraestrutura; PaaS: plataforma."},{"id":3506,"materia":"dados","nivel":2,"enunciado":"Em Python, a biblioteca mais usada para manipular tabelas de dados (DataFrames) é a:","opcoes":["pandas","Django","Flask","Tkinter"],"explicacao":"NumPy cuida de arrays; scikit-learn, de aprendizado de máquina."},{"id":3507,"materia":"dados","nivel":2,"enunciado":"O Redis é classificado como banco NoSQL do tipo:","opcoes":["Chave-valor","Grafo","Documento","Relacional"],"explicacao":"Muito usado como cache em memória."},{"id":3508,"materia":"dados","nivel":2,"enunciado":"O Cassandra é um banco NoSQL do tipo:","opcoes":["Colunar (família de colunas)","Grafo","Chave-valor puro","Relacional"],"explicacao":"Projetado para grande escala distribuída."},{"id":3509,"materia":"dados","nivel":2,"enunciado":"Em séries temporais, a sazonalidade é:","opcoes":["Um padrão que se repete em intervalos regulares, como meses ou estações","A tendência de longo prazo","Um erro de digitação nos dados coletados ao longo dos meses e anos","A média de todo o período"],"explicacao":"Ex.: vendas maiores todo dezembro."},{"id":3510,"materia":"dados","nivel":2,"enunciado":"No processamento de linguagem natural, a tokenização consiste em:","opcoes":["Dividir o texto em unidades menores, como palavras","Traduzir o texto para outro idioma automaticamente","Criptografar o texto","Converter o texto em áudio"],"explicacao":"Etapa inicial de muitos sistemas de PLN."},{"id":3511,"materia":"dados","nivel":2,"enunciado":"A análise de sentimento, em PLN, procura identificar:","opcoes":["Se um texto expressa opinião positiva, negativa ou neutra","O autor de um texto anônimo publicado na internet","O idioma de origem","O número de páginas"],"explicacao":"Usada em redes sociais e atendimento."},{"id":3512,"materia":"dados","nivel":3,"enunciado":"O teorema CAP afirma que um sistema distribuído não garante simultaneamente:","opcoes":["Consistência, disponibilidade e tolerância a partição","Velocidade, volume e variedade","Integridade, autenticidade e sigilo das informações","Leitura, escrita e exclusão"],"explicacao":"Só é possível garantir plenamente dois dos três."},{"id":3513,"materia":"dados","nivel":3,"enunciado":"Na matriz de confusão, o recall (sensibilidade) mede:","opcoes":["A proporção de positivos reais que o modelo acertou","A proporção total de acertos","O tempo de treinamento","O número de variáveis usadas no modelo"],"explicacao":"Precisão mede quantos dos previstos como positivos eram positivos."},{"id":3514,"materia":"dados","nivel":3,"enunciado":"A validação cruzada é usada para:","opcoes":["Avaliar a capacidade de generalização do modelo em dados não vistos","Apagar dados duplicados","Criptografar a base de treino antes de enviá-la ao servidor na nuvem","Acelerar a internet"],"explicacao":"Ex.: k-fold."},{"id":3515,"materia":"dados","nivel":3,"enunciado":"O HDFS, do ecossistema Hadoop, é:","opcoes":["Um sistema de arquivos distribuído","Uma linguagem de consulta relacional","Um antivírus para servidores","Um editor de planilhas"],"explicacao":"Armazena grandes volumes em vários nós."},{"id":3516,"materia":"dados","nivel":3,"enunciado":"Na governança de dados, o data steward é o responsável por:","opcoes":["Zelar pela qualidade e pelo uso correto de um conjunto de dados","Vender os dados a terceiros","Programar o sistema operacional","Fazer a manutenção física dos servidores e cabos de rede"],"explicacao":"Atua como guardião do dado no negócio."},{"id":3517,"materia":"dados","nivel":4,"enunciado":"Os bancos de dados relacionais tradicionais seguem as propriedades ACID, que significam:","opcoes":["Atomicidade, consistência, isolamento e durabilidade","Acesso, controle, integração e disponibilidade","Análise, coleta, indexação e distribuição","Autenticação, criptografia, integridade e disponibilidade dos dados"],"explicacao":"Muitos NoSQL seguem o modelo BASE."},{"id":3518,"materia":"dados","nivel":4,"enunciado":"A árvore de decisão é um modelo de aprendizado de máquina que:","opcoes":["Divide os dados em regras sucessivas do tipo 'se... então'","Só funciona com imagens","Não pode ser interpretado por pessoas, por ser uma caixa-preta","Dispensa dados de treino"],"explicacao":"É um dos modelos mais fáceis de explicar."},{"id":3519,"materia":"trib","nivel":1,"enunciado":"A elisão fiscal se diferencia da evasão porque:","opcoes":["É lícita e ocorre, em regra, antes do fato gerador","É sempre crime","Ocorre depois do lançamento","Depende de autorização judicial prévia"],"explicacao":"Evasão é ilícita, como a sonegação."},{"id":3520,"materia":"trib","nivel":1,"enunciado":"O 13º salário, no imposto de renda da pessoa física, sofre tributação:","opcoes":["Exclusiva na fonte","Somente no ajuste anual","Pelo carnê-leão","Nenhuma, pois é isento"],"explicacao":"Não entra na declaração de ajuste com os demais rendimentos."},{"id":3521,"materia":"trib","nivel":2,"enunciado":"No lucro real, a compensação de prejuízos fiscais de anos anteriores fica limitada a:","opcoes":["30% do lucro real do período","50% do lucro real","10% do lucro real","100% do lucro real do período"],"explicacao":"A chamada 'trava dos 30%'."},{"id":3522,"materia":"trib","nivel":2,"enunciado":"Para fins de IPI, o importador é considerado:","opcoes":["Estabelecimento equiparado a industrial","Contribuinte isento","Simples comerciante sem tributação de IPI","Substituto do consumidor final"],"explicacao":"Regulamento do IPI."},{"id":3523,"materia":"trib","nivel":2,"enunciado":"Em regra, as empresas tributadas pelo lucro presumido recolhem PIS e Cofins pelo regime:","opcoes":["Cumulativo","Não cumulativo","Monofásico obrigatório","Simples Nacional"],"explicacao":"As do lucro real, em regra, pelo não cumulativo."},{"id":3524,"materia":"trib","nivel":2,"enunciado":"A venda do único imóvel residencial da pessoa física é isenta do IR sobre ganho de capital se o valor for de até:","opcoes":["R$ 440 mil, sem outra venda nos últimos 5 anos","R$ 1 milhão, sem limite de vendas no período","R$ 100 mil, uma vez por ano","R$ 50 mil, a qualquer tempo"],"explicacao":"Art. 23 da Lei 9.250/1995."},{"id":3525,"materia":"trib","nivel":3,"enunciado":"No processo administrativo fiscal federal, o julgamento em primeira instância cabe às:","opcoes":["Delegacias de Julgamento da Receita Federal (DRJ)","Varas da Justiça Federal","Câmaras do CARF","Procuradorias da Fazenda Nacional nos estados"],"explicacao":"O CARF julga os recursos em segunda instância."},{"id":3526,"materia":"trib","nivel":3,"enunciado":"São contribuintes da CIDE-Combustíveis:","opcoes":["O produtor, o formulador e o importador de combustíveis","Os postos de gasolina","Os consumidores finais","As distribuidoras de energia elétrica e de gás canalizado"],"explicacao":"Lei 10.336/2001, art. 2º."},{"id":3527,"materia":"trib","nivel":3,"enunciado":"Os ganhos de capital da pessoa física são tributados pelo IR com alíquotas de:","opcoes":["15% a 22,5%, conforme o valor do ganho","27,5% fixos","5% a 10%","Alíquota única de 1% sobre a venda"],"explicacao":"Art. 21 da Lei 8.981/1995, com redação da Lei 13.259/2016."},{"id":3528,"materia":"trib","nivel":4,"enunciado":"O pagamento integral do tributo, inclusive acessórios, nos crimes contra a ordem tributária:","opcoes":["Extingue a punibilidade","Apenas reduz a pena","Não tem qualquer efeito penal","Só vale antes da denúncia, em qualquer caso"],"explicacao":"Art. 9º, § 2º da Lei 10.684/2003, conforme a jurisprudência do STF e STJ."},{"id":3529,"materia":"prev","nivel":2,"enunciado":"Pela LC 150/2015, o empregador doméstico recolhe contribuição previdenciária patronal de:","opcoes":["8%","20%","12%","2%"],"explicacao":"Além de 0,8% de seguro contra acidentes, FGTS e indenização compensatória."},{"id":3530,"materia":"prev","nivel":2,"enunciado":"O produtor rural pessoa física contribui para a seguridade, em regra, sobre:","opcoes":["A receita bruta da comercialização da produção","O valor da terra","A folha de salários apenas, como as empresas","O lucro líquido anual"],"explicacao":"Art. 25 da Lei 8.212/1991."},{"id":3531,"materia":"prev","nivel":3,"enunciado":"As empresas que integram grupo econômico respondem pelas contribuições previdenciárias de forma:","opcoes":["Solidária","Subsidiária","Proporcional ao capital","Nenhuma"],"explicacao":"Art. 30, IX da Lei 8.212/1991."},{"id":3532,"materia":"prev","nivel":3,"enunciado":"Em regra, a empresa deve recolher as contribuições previdenciárias até o dia:","opcoes":["20 do mês seguinte ao da competência","5 do mês seguinte","último dia útil do mês seguinte","10 do próprio mês"],"explicacao":"Antecipa-se se não houver expediente bancário."},{"id":3533,"materia":"prev","nivel":4,"enunciado":"O Conselho Nacional de Previdência Social (CNPS) tem, segundo a Lei 8.213/1991:","opcoes":["6 representantes do governo e 9 da sociedade civil","15 representantes do governo","Apenas representantes dos aposentados e pensionistas","3 representantes de cada Poder"],"explicacao":"Os 9 da sociedade civil dividem-se entre aposentados, trabalhadores e empregadores."},{"id":3534,"materia":"prev","nivel":4,"enunciado":"Suprimir ou reduzir contribuição previdenciária omitindo segurados da folha de pagamento é o crime de:","opcoes":["Sonegação de contribuição previdenciária","Apropriação indébita previdenciária","Estelionato","Falsidade ideológica simples em documento particular"],"explicacao":"Art. 337-A do Código Penal."},{"id":3535,"materia":"eco","nivel":1,"enunciado":"O PIB nominal se diferencia do PIB real porque o nominal:","opcoes":["É medido a preços correntes, sem descontar a inflação","Exclui os gastos do governo","Inclui a renda enviada ao exterior","É calculado apenas a cada dez anos, junto com o censo"],"explicacao":"O PIB real é calculado a preços constantes."},{"id":3536,"materia":"eco","nivel":2,"enunciado":"A diferença entre o PIB e o PNB está:","opcoes":["Na renda líquida enviada ou recebida do exterior","Nos impostos indiretos sobre o consumo das famílias","Na depreciação do capital fixo","Nos gastos correntes do governo"],"explicacao":"PNB = PIB − renda líquida enviada ao exterior."},{"id":3537,"materia":"aud","nivel":2,"enunciado":"Na NBC TA 505, a confirmação negativa é aquela em que o terceiro responde:","opcoes":["Apenas se discordar das informações enviadas","Sempre, concordando ou não","Somente por telefone ao auditor","Somente ao cliente, e não diretamente ao auditor"],"explicacao":"Na confirmação positiva, a resposta é pedida em qualquer caso."},{"id":3538,"materia":"prev","nivel":3,"enunciado":"Na Lei 8.212/1991, os limites mínimo e máximo do salário de contribuição são, respectivamente:","opcoes":["O salário mínimo (ou piso) e o teto do RGPS","Meio salário mínimo e dez salários mínimos por mês","Zero e o subsídio de ministro do STF","Um salário mínimo e cinco salários mínimos"],"explicacao":"Art. 28, §§ 3º e 5º."}]$q$::jsonb)
  as x(id integer, materia text, nivel smallint, enunciado text, opcoes jsonb, explicacao text)
on conflict (id) do update set materia = excluded.materia, nivel = excluded.nivel, enunciado = excluded.enunciado, opcoes = excluded.opcoes, explicacao = excluded.explicacao;

select setval(pg_get_serial_sequence('public.questoes', 'id'), (select max(id) from public.questoes));
select materia, count(*) as questoes from public.questoes where materia in ('adua','eco','aud','dados') group by materia order by materia;
select count(*) as total_de_questoes from public.questoes;
